import{_ as i,c as o,a5 as e,o as t}from"./chunks/framework.mFcBg5UA.js";const r="/my-blog/question/vue/vue2_vue3.jpg",s="/my-blog/question/vue/vue2_vue3_1.png",h=JSON.parse('{"title":"Vue2 和 Vue3对比","titleTemplate":"前端面试题","description":"","frontmatter":{"outline":"deep","title":"Vue2 和 Vue3对比","titleTemplate":"前端面试题","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/question/vue/vue2_vue3.html"}]]},"headers":[],"relativePath":"question/vue/vue2_vue3.md","filePath":"question/vue/vue2_vue3.md","lastUpdated":1724510899000}'),u={name:"question/vue/vue2_vue3.md"};function n(a,l,g,p,V,d){return t(),o("div",null,l[0]||(l[0]=[e('<h1 id="vue2-和-vue3对比" tabindex="-1">Vue2 和 Vue3对比 <a class="header-anchor" href="#vue2-和-vue3对比" aria-label="Permalink to &quot;Vue2 和 Vue3对比&quot;">​</a></h1><img src="'+r+'" width="500" height="520"><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><p>主要是数据响应式上的区别，这也是最核心的区别<br><strong>Vue.js 2的响应式：</strong></p><ol><li><strong>Object.defineProperty：</strong> Vue.js 2使用<code>Object.defineProperty</code>来监听对象的属性访问和修改。当一个对象被传递给Vue实例的<code>data</code>选项时，Vue会遍历对象的每个属性，并使用<code>Object.defineProperty</code>将其转换为&quot;响应式&quot;的属性。这样一来，当数据发生变化时，Vue就能捕获到变化，并触发视图的更新。</li><li><strong>依赖追踪：</strong> 在Vue.js 2中，每当视图（模板）访问一个响应式对象的属性时，Vue会在背后建立起一个依赖关系。这样，当属性发生改变时，Vue就能够找到对应的依赖，进而更新相关的视图。</li><li><strong>数组变异方法：</strong> 由于<code>Object.defineProperty</code>只能监听对象的属性访问和修改，Vue.js 2对于数组的响应式处理需要特殊处理。Vue.js 2通过重写了数组的原型方法，如<code>push</code>、<code>pop</code>、<code>splice</code>等，使得这些方法在被调用时能够触发视图的更新。</li></ol><p><strong>Vue.js 3的响应式：</strong></p><ol><li><strong>ES6 Proxy：</strong> Vue.js 3采用了ES6的<code>Proxy</code>代理，这是JavaScript的一种新特性。Proxy可以拦截并重定义对象上的操作，使得可以监听到对象的任何属性的访问和修改。</li><li><strong>依赖追踪优化：</strong> Vue.js 3在依赖追踪方面进行了优化，将其与Proxy相结合，从而更高效地进行数据追踪和更新。这也使得在Vue.js 3中，对数组的处理更加自然，无需像Vue.js 2一样重写数组的原型方法。</li><li><strong>Composition API支持：</strong> Vue.js 3的Composition API使得对数据的处理更加灵活，可以更好地组织组件逻辑，并减少了在大型应用中的数据追踪和管理的复杂性。</li></ol><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><p>主要区别是Vue3合并了一些钩子,同时新增了几个钩子,并通过组合式API让用户获得更多自定义钩子的灵活性。这些改变使得生命周期之间的关联更加清晰,也给用户提供了更好的逻辑组织方式。下面是一个比较列表</p><img src="'+s+'"><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><ol><li><strong>数据监听机制</strong></li></ol><p>Vue2通过Object.defineProperty()进行数据劫持,需要遍历所有属性,有一定性能开销。<br>Vue3使用Proxy代理数据,直接监听对象,减少遍历属性时间,性能更好。</p><ol start="2"><li><strong>编译优化</strong></li></ol><p>Vue3对编译过程进行了优化,静态节点提升,缓存事件处理函数等,启动速度比Vue2<strong>快10-100倍</strong>。</p><ol start="3"><li><strong>包体积</strong></li></ol><p>Vue3移除了一些不常用的API,并优化了Tree-Shaking,使打包体积相比Vue2小<strong>10%左右</strong>。</p><ol start="4"><li><strong>内存占用</strong></li></ol><p>Vue3中移除了一些内存占用高的功能,同时优化了部分内存分配,降低内存消耗。</p><ol start="5"><li><strong>SSR优化</strong></li></ol><p>Vue3使用异步SSR,大大减少主线程执行代码量,提升服务器端渲染性能。<br>Vue3可以说在初始化、渲染、内存占用等多个方面对Vue2有很大的性能提升，这使得Vue3可以承载更复杂的应用场景。</p><h2 id="编码方式" tabindex="-1">编码方式 <a class="header-anchor" href="#编码方式" aria-label="Permalink to &quot;编码方式&quot;">​</a></h2><ol><li><strong>Options API 和 Composition API</strong></li></ol><p>Vue2通过Options API进行编码,逻辑分散,不便于重用。<br>Vue3引入Composition API,基于函数式编程,代码更聚合。</p><ol start="2"><li><strong>definingComponent</strong></li></ol><p>Vue3通过definingComponent API定义组件,语法更清晰。</p><ol start="3"><li><strong>Ref 和 Reactive</strong></li></ol><p>Vue3通过Ref和Reactive API声明响应式变量,语法更简洁。</p><ol start="4"><li><strong>setup</strong></li></ol><p>Vue3中通过setup函数统一声明逻辑。Vue2逻辑分散在多个选项中。</p><ol start="5"><li><strong>异步组件</strong></li></ol><p>Vue3直接支持返回Promise的异步组件。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><ol><li><strong>Options API 和 Composition API</strong></li></ol><ul><li>Vue2中主要通过Options API进行开发,如data、methods等。</li><li>Vue3推荐使用Composition API,如ref、reactive、watch、computed等。</li></ul><ol start="2"><li><strong>移除过滤器(filter)</strong></li></ol><ul><li>Vue2中可以使用filter对数据进行转换后显示。</li><li>Vue3移除了filter,推荐使用方法或计算属性代替。</li></ul><ol start="3"><li><strong>全局和内实例API调整</strong></li></ol><ul><li>Vue3删除了一些不常用的全局和内实例API，并做了功能调整,如$on改为app.config.globalProperties。</li></ul><ol start="4"><li><strong>源码级API</strong></li></ol><ul><li>Vue3暴露了部分源码API用于扩展,如createRenderer。</li></ul><h2 id="diff-算法" tabindex="-1">Diff 算法 <a class="header-anchor" href="#diff-算法" aria-label="Permalink to &quot;Diff 算法&quot;">​</a></h2><ol><li><strong>静态标记</strong></li></ol><ul><li>Vue2 中通过标记静态根节点,跳过对这部分的Diff。</li><li>Vue3 使用Shape Flags更精确地标记静态根,提高Diff效率。</li></ul><ol start="2"><li><strong>优化逻辑</strong></li></ol><ul><li>Vue.js 2使用了比较经典的双指针（双端比较）的Diff算法。当进行Virtual DOM的更新时，Vue.js 2会比较新的Virtual DOM和旧的Virtual DOM，找出需要更新的节点并最小化更新DOM。</li><li>Vue.js 3对Diff算法进行了优化，采用了更加高效的单端比较的Diff算法。在Vue.js 3中，每个VNode都有一个唯一的标识，这个标识在更新时被用来进行快速的节点匹配和查找。</li></ul><ol start="3"><li><strong>分块对比</strong></li></ol><ul><li>Vue3 支持对相邻重复节点进行分块比较,减少冗余Diff。</li><li>如列表中连续相同文本节点进行合并比较。</li></ul><ol start="4"><li><strong>异步渲染</strong></li></ol><ul><li>Vue3 支持组件异步渲染,等待组件完成再进行Diff。</li><li>避免无效对比,提高性能。</li></ul><ol start="5"><li><strong>代码减少</strong></li></ol><ul><li>Vue3 对核心Diff逻辑进行了裁剪,移除了冗余代码。</li><li>优化后代码量减少超过40%。</li></ul><ol start="6"><li><strong>SSR Diff</strong></li></ol><ul><li>Vue3 新增了 SSR 环境下的 Diff 优化模式。</li><li>避免不必要客户端对比,加快渲染速度。</li></ul><h2 id="打包构建" tabindex="-1">打包构建 <a class="header-anchor" href="#打包构建" aria-label="Permalink to &quot;打包构建&quot;">​</a></h2><ol><li><strong>打包体积</strong></li></ol><ul><li>Vue3移除了一些不常用的API,同时优化了Tree-shaking。</li><li>与Vue2相比,打包后体积减小约10%。</li></ul><ol start="2"><li><strong>依赖优化</strong></li></ol><ul><li>Vue3对依赖进行了优化,裁剪不必要代码,减少冗余。</li></ul><ol start="3"><li><strong>构建速度</strong></li></ol><ul><li>Vue3改进了编译过程,提高了构建速度。</li><li>特别是prod模式下打包速度明显加快。</li></ul><ol start="4"><li><strong>编译优化</strong></li></ol><ul><li>Vue3改用优化的自动化持久缓存,加速增量编译。</li><li>配合新语法提升热重载速度。</li></ul><ol start="5"><li><strong>Tree-shaking</strong></li></ol><ul><li>Vue3编译支持更精确的Tree-shaking,删除无用代码。</li><li>如自动Tree-shaking样式表。</li></ul><ol start="6"><li><strong>模块化</strong></li></ol><ul><li>Vue3源码实现了高度的ESM模块化。</li><li>更好的支持Tree-shaking、懒加载等能力。</li></ul><ol start="7"><li><strong>新特性支持</strong></li></ol><ul><li>Vue3内置支持了碎片、Teleport、Suspense等新特性。</li></ul><h2 id="typescript支持" tabindex="-1">TypeScript支持 <a class="header-anchor" href="#typescript支持" aria-label="Permalink to &quot;TypeScript支持&quot;">​</a></h2><ol><li><strong>内部实现</strong></li></ol><ul><li>Vue2源码是JavaScript编写,需要手动维护类型定义。</li><li>Vue3源码直接采用TypeScript重写,类型信息内置。</li></ul><ol start="2"><li><strong>组件定义</strong></li></ol><ul><li>Vue2使用.vue文件,需要额外的vue-class-component decorators。</li><li>Vue3可以直接以类的形式定义组件,更纯粹的TS体验。</li></ul><ol start="3"><li><strong>Options API</strong></li></ol><ul><li>Vue2的Options API缺乏类型推导。</li><li>Vue3增强了对Options API的类型推导。</li></ul><ol start="4"><li><strong>Composition API</strong></li></ol><ul><li>Vue3的Composition API全面采用泛型、接口等TS新语法。</li><li>提供完整的类型支持。</li></ul><ol start="5"><li><strong>引用注册</strong></li></ol><ul><li>Vue3改用统一的<code>defineComponent</code>方法注册组件。</li><li>提供完整的Props检验和IDE提示。</li></ul><ol start="6"><li><strong>TS配置</strong></li></ol><ul><li>Vue3优化了<code>tsconfig.json</code>,提供更严谨的TS类型检查。</li></ul><ol start="7"><li><strong>内置工具类型</strong></li></ol><ul><li>Vue3导出了部分内置工具的TS类型,增强扩展性。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总体而言,Vue3对Vue2进行了全方位的升级:</p><ol><li>性能上,Vue3做了很多优化,无论是初始化速度还是渲染效率都有显著提高。</li><li>功能上,Vue3添加了Composition API、Fragment、Teleport等前沿特性。</li><li>架构上,Vue3使用TypeScript重写了代码,整体架构更加清晰优雅。</li><li>API上,废弃了一些API,新增了组合式API,提高了开发效率。</li><li>组织上,推荐函数式编程和hooks,使代码逻辑更加聚合。</li><li>构建上,改进了编译和Treeshaking,使打包速度和体积都得到优化。</li><li>生态上,Vue3的升级将促进相关工具链的进一步完善。</li></ol>',87)]))}const f=i(u,[["render",n]]);export{h as __pageData,f as default};
